INSERT IGNORE INTO reporting_queries (slug, name, description, sql_query, is_system)
VALUES
('rmm-agents-by-company', 'RMM: Agent Coverage and Status by Company', 'Active RMM agents per company with online (seen in the last 15 minutes), offline, offline-over-7-days and per-platform counts.', 'SELECT c.name AS company, COUNT(*) AS agents, SUM(CASE WHEN ag.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 15 MINUTE THEN 1 ELSE 0 END) AS online, SUM(CASE WHEN ag.last_seen_utc IS NULL OR ag.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 15 MINUTE THEN 1 ELSE 0 END) AS offline, SUM(CASE WHEN ag.last_seen_utc IS NULL OR ag.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 7 DAY THEN 1 ELSE 0 END) AS offline_over_7_days, SUM(CASE WHEN ag.os = ''windows'' THEN 1 ELSE 0 END) AS windows, SUM(CASE WHEN ag.os = ''darwin'' THEN 1 ELSE 0 END) AS macos, SUM(CASE WHEN ag.os = ''linux'' THEN 1 ELSE 0 END) AS linux, MAX(ag.last_seen_utc) AS last_check_in_utc FROM rmm_agents ag LEFT JOIN companies c ON c.id = ag.company_id WHERE ag.status = ''active'' GROUP BY ag.company_id, c.name ORDER BY agents DESC, company', 1),
('rmm-agents-offline-over-7-days', 'RMM: Agents Offline for More Than 7 Days', 'Active RMM agents that have not checked in for over 7 days, oldest first, with the linked asset and days offline.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, ag.hostname, ag.os, ag.os_version, ag.agent_version, ag.last_ip, ag.last_seen_utc, TIMESTAMPDIFF(DAY, ag.last_seen_utc, UTC_TIMESTAMP()) AS days_offline FROM rmm_agents ag LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE ag.status = ''active'' AND (ag.last_seen_utc IS NULL OR ag.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 7 DAY) ORDER BY ag.last_seen_utc IS NULL DESC, ag.last_seen_utc ASC', 1),
('rmm-agent-version-distribution', 'RMM: Agent Version Distribution', 'Active RMM agents grouped by platform and agent version, with how many support script files, run-as-user and run-anyway.', 'SELECT ag.os AS platform, COALESCE(ag.agent_version, ''unknown'') AS agent_version, COUNT(*) AS agents, SUM(ag.script_files_supported) AS script_files_supported, SUM(ag.run_as_user_supported) AS run_as_user_supported, SUM(ag.run_anyway_supported) AS run_anyway_supported, MAX(ag.last_seen_utc) AS last_check_in_utc FROM rmm_agents ag WHERE ag.status = ''active'' GROUP BY ag.os, ag.agent_version ORDER BY platform, agents DESC', 1),
('rmm-agent-install-attempts-last-30-days', 'RMM: Agent Install Attempts (Last 30 Days)', 'RMM agent deployment attempts in the last 30 days by company, source (auto, manual, repair) and outcome.', 'SELECT c.name AS company, i.source, i.outcome, COUNT(*) AS attempts, MAX(i.created_at) AS last_attempt_at FROM rmm_agent_install_attempts i LEFT JOIN companies c ON c.id = i.company_id WHERE i.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY i.company_id, c.name, i.source, i.outcome ORDER BY company, attempts DESC', 1),
('rmm-agent-deployment-gaps', 'RMM: Tray Devices Without an RMM Agent', 'Active tray devices that have no active RMM agent yet, with the company''s automatic deployment setting and the latest install attempt.', 'SELECT c.name AS company, td.hostname, td.os, td.os_version, td.agent_version AS tray_version, td.last_seen_utc, CASE WHEN c.rmm_agent_auto_deploy = 1 THEN ''yes'' ELSE ''no'' END AS auto_deploy_enabled, (SELECT i.outcome FROM rmm_agent_install_attempts i WHERE i.tray_device_id = td.id ORDER BY i.created_at DESC, i.id DESC LIMIT 1) AS last_install_outcome, (SELECT i.message FROM rmm_agent_install_attempts i WHERE i.tray_device_id = td.id ORDER BY i.created_at DESC, i.id DESC LIMIT 1) AS last_install_message, (SELECT MAX(i.created_at) FROM rmm_agent_install_attempts i WHERE i.tray_device_id = td.id) AS last_install_attempt_at FROM tray_devices td LEFT JOIN companies c ON c.id = td.company_id WHERE td.status = ''active'' AND NOT EXISTS (SELECT 1 FROM rmm_agents ag WHERE ag.tray_device_id = td.id AND ag.status = ''active'') ORDER BY company, td.hostname', 1),
('rmm-hardware-inventory', 'RMM Inventory: Hardware Summary', 'Latest RMM hardware inventory per device: manufacturer, model, serial, BIOS, CPU, memory, disk capacity, free system disk and last boot.', 'SELECT c.name AS company, COALESCE(a.name, inv.hostname) AS device, inv.manufacturer, inv.model, inv.serial_number, inv.bios_version, inv.os_name, inv.os_version, inv.os_build, inv.cpu_model, inv.cpu_cores, inv.cpu_logical_processors, ROUND(inv.ram_bytes / 1073741824, 1) AS ram_gb, ROUND(inv.disk_total_bytes / 1073741824, 0) AS disk_total_gb, ROUND(inv.system_disk_free_bytes / 1073741824, 1) AS system_disk_free_gb, inv.last_boot_at, inv.software_count, inv.collected_at FROM rmm_device_inventory inv LEFT JOIN companies c ON c.id = inv.company_id LEFT JOIN assets a ON a.id = inv.asset_id ORDER BY company, device', 1),
('rmm-inventory-manufacturer-model', 'RMM Inventory: Devices by Manufacturer and Model', 'Device counts by manufacturer and model from RMM inventory, with average memory and the oldest and newest BIOS seen.', 'SELECT COALESCE(NULLIF(inv.manufacturer, ''''), ''Unknown'') AS manufacturer, COALESCE(NULLIF(inv.model, ''''), ''Unknown'') AS model, COUNT(*) AS devices, COUNT(DISTINCT inv.company_id) AS companies, ROUND(AVG(inv.ram_bytes) / 1073741824, 1) AS avg_ram_gb, MIN(inv.bios_version) AS min_bios_version, MAX(inv.bios_version) AS max_bios_version FROM rmm_device_inventory inv GROUP BY manufacturer, model ORDER BY devices DESC, manufacturer, model', 1),
('rmm-inventory-os-builds', 'RMM Inventory: Operating System Builds', 'Device counts by operating system name, version and build from RMM inventory, to spot out-of-date feature releases.', 'SELECT COALESCE(inv.os_name, ''Unknown'') AS os_name, inv.os_version, inv.os_build, COUNT(*) AS devices, COUNT(DISTINCT inv.company_id) AS companies, MAX(inv.collected_at) AS latest_inventory FROM rmm_device_inventory inv GROUP BY inv.os_name, inv.os_version, inv.os_build ORDER BY os_name, inv.os_version, inv.os_build', 1),
('rmm-inventory-low-system-disk', 'RMM Inventory: Low System Disk Space', 'Devices whose system disk has less than 15% or less than 20 GB free, lowest free space first.', 'SELECT c.name AS company, COALESCE(a.name, inv.hostname) AS device, inv.os_name, ROUND(inv.system_disk_free_bytes / 1073741824, 1) AS system_disk_free_gb, ROUND(inv.disk_total_bytes / 1073741824, 0) AS disk_total_gb, ROUND(100 * inv.system_disk_free_bytes / NULLIF(inv.disk_total_bytes, 0), 1) AS free_percent_of_total_disk, inv.collected_at FROM rmm_device_inventory inv LEFT JOIN companies c ON c.id = inv.company_id LEFT JOIN assets a ON a.id = inv.asset_id WHERE inv.system_disk_free_bytes IS NOT NULL AND (inv.system_disk_free_bytes < 21474836480 OR inv.system_disk_free_bytes < 0.15 * NULLIF(inv.disk_total_bytes, 0)) ORDER BY inv.system_disk_free_bytes ASC', 1),
('rmm-inventory-low-memory', 'RMM Inventory: Devices With Less Than 8 GB RAM', 'Devices reporting under 8 GB of memory in RMM inventory, typically hardware refresh candidates.', 'SELECT c.name AS company, COALESCE(a.name, inv.hostname) AS device, inv.manufacturer, inv.model, inv.os_name, ROUND(inv.ram_bytes / 1073741824, 1) AS ram_gb, inv.cpu_model, inv.collected_at FROM rmm_device_inventory inv LEFT JOIN companies c ON c.id = inv.company_id LEFT JOIN assets a ON a.id = inv.asset_id WHERE inv.ram_bytes IS NOT NULL AND inv.ram_bytes < 8589934592 ORDER BY inv.ram_bytes ASC, company, device', 1),
('rmm-inventory-long-uptime', 'RMM Inventory: Devices Not Restarted in 30 Days', 'Online RMM devices whose last boot was more than 30 days ago, longest uptime first.', 'SELECT c.name AS company, COALESCE(a.name, inv.hostname) AS device, inv.os_name, inv.last_boot_at, TIMESTAMPDIFF(DAY, inv.last_boot_at, UTC_TIMESTAMP()) AS uptime_days, ag.last_seen_utc FROM rmm_device_inventory inv JOIN rmm_agents ag ON ag.id = inv.agent_id LEFT JOIN companies c ON c.id = inv.company_id LEFT JOIN assets a ON a.id = inv.asset_id WHERE ag.status = ''active'' AND ag.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 2 DAY AND inv.last_boot_at < UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY inv.last_boot_at ASC', 1),
('rmm-inventory-stale', 'RMM Inventory: Stale or Missing Inventory', 'Active RMM agents with no inventory or an inventory older than 7 days.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, ag.os, ag.last_seen_utc, inv.collected_at AS inventory_collected_at, inv.received_at AS inventory_received_at, inv.refresh_requested_at FROM rmm_agents ag LEFT JOIN rmm_device_inventory inv ON inv.agent_id = ag.id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE ag.status = ''active'' AND (inv.id IS NULL OR inv.received_at IS NULL OR inv.received_at < UTC_TIMESTAMP() - INTERVAL 7 DAY) ORDER BY inv.received_at IS NULL DESC, inv.received_at ASC', 1),
('rmm-software-most-installed', 'RMM Software: Most Installed Applications', 'Applications from RMM software inventory ranked by the number of devices they are installed on, with version and company spread.', 'SELECT s.name, MAX(s.publisher) AS publisher, COUNT(DISTINCT s.agent_id) AS devices, COUNT(DISTINCT ag.company_id) AS companies, COUNT(DISTINCT s.version) AS distinct_versions, MAX(s.version) AS highest_version FROM rmm_device_software s JOIN rmm_agents ag ON ag.id = s.agent_id WHERE ag.status = ''active'' GROUP BY s.name ORDER BY devices DESC, s.name', 1),
('rmm-software-version-drift', 'RMM Software: Applications Running Multiple Versions', 'Applications installed in more than one version across active devices, with the number of devices on each version.', 'SELECT s.name, COALESCE(s.version, ''unknown'') AS version, COUNT(DISTINCT s.agent_id) AS devices, COUNT(DISTINCT ag.company_id) AS companies FROM rmm_device_software s JOIN rmm_agents ag ON ag.id = s.agent_id WHERE ag.status = ''active'' AND s.name IN ( SELECT s2.name FROM rmm_device_software s2 JOIN rmm_agents ag2 ON ag2.id = s2.agent_id WHERE ag2.status = ''active'' GROUP BY s2.name HAVING COUNT(DISTINCT s2.version) > 1) GROUP BY s.name, s.version ORDER BY s.name, devices DESC', 1),
('rmm-software-devices-with-application', 'RMM Software: Devices With an Application', 'Every device with a matching application installed. Clone and replace "Chrome" in the filter with the application to find.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, s.name AS application, s.version, s.publisher, s.install_date, s.source, ag.last_seen_utc FROM rmm_device_software s JOIN rmm_agents ag ON ag.id = s.agent_id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE ag.status = ''active'' AND s.name LIKE ''%Chrome%'' ORDER BY company, device, application', 1),
('rmm-software-changes-last-30-days', 'RMM Software: Installs and Removals (Last 30 Days)', 'Software first seen or removed on a device in the last 30 days from RMM software history, newest first.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, h.name AS application, h.version, h.publisher, CASE WHEN h.removed_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY THEN ''removed'' ELSE ''installed'' END AS change_kind, COALESCE(h.removed_at, h.first_seen_at) AS changed_at FROM rmm_device_software_history h JOIN rmm_agents ag ON ag.id = h.agent_id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE h.first_seen_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY OR h.removed_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY changed_at DESC', 1),
('rmm-software-change-volume-by-company', 'RMM Software: Change Volume by Company (Last 30 Days)', 'Counts of software installs, upgrades and removals detected by RMM Findings per company in the last 30 days.', 'SELECT c.name AS company, SUM(CASE WHEN sc.change_type = ''installed'' THEN 1 ELSE 0 END) AS installed, SUM(CASE WHEN sc.change_type = ''updated'' THEN 1 ELSE 0 END) AS updated, SUM(CASE WHEN sc.change_type = ''removed'' THEN 1 ELSE 0 END) AS removed, COUNT(DISTINCT sc.agent_id) AS devices_changed, MAX(sc.detected_at) AS last_change_at FROM rmm_finding_software_changes sc LEFT JOIN companies c ON c.id = sc.company_id WHERE sc.detected_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY sc.company_id, c.name ORDER BY COUNT(*) DESC', 1),
('rmm-software-chocolatey-version-gaps', 'RMM Software: Chocolatey Packages Behind the Catalogue', 'Installed applications matched to a Chocolatey package whose installed version differs from the latest version in the Chocolatey catalogue.', 'SELECT s.name AS application, m.package_id, p.version AS catalogue_version, s.version AS installed_version, COUNT(DISTINCT s.agent_id) AS devices, COUNT(DISTINCT ag.company_id) AS companies FROM rmm_device_software s JOIN rmm_agents ag ON ag.id = s.agent_id JOIN rmm_chocolatey_software_matches m ON m.name = s.name JOIN rmm_chocolatey_packages p ON p.package_id = m.package_id WHERE ag.status = ''active'' AND s.version IS NOT NULL AND s.version <> p.version GROUP BY s.name, m.package_id, p.version, s.version ORDER BY devices DESC, application', 1),
('rmm-windows-updates-missing-by-device', 'Windows Updates: Missing Updates by Device', 'Latest Windows Update scan per device with missing, security and critical update counts, pending reboot and scan age.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, sc.missing_count, (SELECT COUNT(*) FROM rmm_windows_updates u WHERE u.agent_id = sc.agent_id AND u.is_hidden = 0 AND u.classification LIKE ''%Security%'') AS security_missing, (SELECT COUNT(*) FROM rmm_windows_updates u WHERE u.agent_id = sc.agent_id AND u.is_hidden = 0 AND u.severity = ''Critical'') AS critical_missing, CASE WHEN sc.reboot_pending = 1 THEN ''yes'' ELSE ''no'' END AS reboot_pending, sc.update_source, sc.scanned_at, TIMESTAMPDIFF(DAY, sc.scanned_at, UTC_TIMESTAMP()) AS scan_age_days FROM rmm_windows_update_scans sc JOIN rmm_agents ag ON ag.id = sc.agent_id LEFT JOIN companies c ON c.id = sc.company_id LEFT JOIN assets a ON a.id = sc.asset_id WHERE ag.status = ''active'' ORDER BY sc.missing_count DESC, company, device', 1),
('rmm-windows-updates-most-missing', 'Windows Updates: Most Commonly Missing Updates', 'Missing (not hidden) Windows updates ranked by the number of devices that need them, with KB, classification and severity.', 'SELECT u.kb, u.title, u.classification, u.severity, u.released_on, COUNT(DISTINCT u.agent_id) AS devices, COUNT(DISTINCT ag.company_id) AS companies, ROUND(MAX(u.size_bytes) / 1048576, 1) AS size_mb, MIN(u.first_seen_at) AS first_seen_at FROM rmm_windows_updates u JOIN rmm_agents ag ON ag.id = u.agent_id WHERE ag.status = ''active'' AND u.is_hidden = 0 GROUP BY u.update_id, u.kb, u.title, u.classification, u.severity, u.released_on ORDER BY devices DESC, u.released_on', 1),
('rmm-windows-updates-missing-by-classification', 'Windows Updates: Missing Updates by Company and Classification', 'Missing (not hidden) Windows updates per company split by classification, counting update instances and affected devices.', 'SELECT c.name AS company, COALESCE(u.classification, ''Unclassified'') AS classification, COUNT(*) AS missing_updates, COUNT(DISTINCT u.agent_id) AS devices FROM rmm_windows_updates u JOIN rmm_agents ag ON ag.id = u.agent_id LEFT JOIN companies c ON c.id = ag.company_id WHERE ag.status = ''active'' AND u.is_hidden = 0 GROUP BY ag.company_id, c.name, u.classification ORDER BY company, missing_updates DESC', 1),
('rmm-windows-updates-failed-installs-30-days', 'Windows Updates: Failed Installs (Last 30 Days)', 'Windows update installs that failed in the last 30 days, with the HRESULT error code and the application that ran the install.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, h.kb, h.title, h.classification, h.hresult, h.client_application, h.source, h.occurred_at FROM rmm_windows_update_history h JOIN rmm_agents ag ON ag.id = h.agent_id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE h.operation = ''install'' AND h.result = ''failed'' AND h.occurred_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY h.occurred_at DESC', 1),
('rmm-windows-updates-failure-codes', 'Windows Updates: Install Failures by Error Code (Last 90 Days)', 'Failed Windows update installs in the last 90 days grouped by HRESULT so recurring causes stand out.', 'SELECT COALESCE(h.hresult, ''none'') AS hresult, COUNT(*) AS failures, COUNT(DISTINCT h.agent_id) AS devices, COUNT(DISTINCT h.kb) AS distinct_kbs, MAX(h.occurred_at) AS last_failure_at FROM rmm_windows_update_history h WHERE h.operation = ''install'' AND h.result = ''failed'' AND h.occurred_at >= UTC_TIMESTAMP() - INTERVAL 90 DAY GROUP BY h.hresult ORDER BY failures DESC', 1),
('rmm-windows-updates-install-history-monthly', 'Windows Updates: Install Results by Month', 'Windows update install operations per month over the last 12 months: succeeded, succeeded with errors, failed and cancelled.', 'SELECT DATE_FORMAT(h.occurred_at, ''%Y-%m'') AS month, COUNT(*) AS installs, SUM(CASE WHEN h.result = ''succeeded'' THEN 1 ELSE 0 END) AS succeeded, SUM(CASE WHEN h.result = ''succeeded_with_errors'' THEN 1 ELSE 0 END) AS succeeded_with_errors, SUM(CASE WHEN h.result = ''failed'' THEN 1 ELSE 0 END) AS failed, SUM(CASE WHEN h.result = ''aborted'' THEN 1 ELSE 0 END) AS cancelled, COUNT(DISTINCT h.agent_id) AS devices FROM rmm_windows_update_history h WHERE h.operation = ''install'' AND h.occurred_at >= UTC_TIMESTAMP() - INTERVAL 12 MONTH GROUP BY month ORDER BY month', 1),
('rmm-windows-updates-reboot-pending', 'Windows Updates: Devices Awaiting a Reboot', 'Active devices whose latest Windows Update scan reports a pending reboot, with last boot and check-in times.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, sc.scanned_at, inv.last_boot_at, ag.last_seen_utc, sc.missing_count FROM rmm_windows_update_scans sc JOIN rmm_agents ag ON ag.id = sc.agent_id LEFT JOIN rmm_device_inventory inv ON inv.agent_id = sc.agent_id LEFT JOIN companies c ON c.id = sc.company_id LEFT JOIN assets a ON a.id = sc.asset_id WHERE ag.status = ''active'' AND sc.reboot_pending = 1 ORDER BY inv.last_boot_at ASC', 1),
('rmm-windows-updates-scan-stale', 'Windows Updates: Devices Not Scanned in 7 Days', 'Active Windows RMM agents with no Windows Update scan, or whose last scan is more than 7 days old.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, ag.os_version, ag.last_seen_utc, sc.scanned_at, sc.scan_requested_at, sc.errors_json AS scan_errors FROM rmm_agents ag LEFT JOIN rmm_windows_update_scans sc ON sc.agent_id = ag.id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE ag.status = ''active'' AND ag.os = ''windows'' AND (sc.scanned_at IS NULL OR sc.scanned_at < UTC_TIMESTAMP() - INTERVAL 7 DAY) ORDER BY sc.scanned_at IS NULL DESC, sc.scanned_at ASC', 1),
('rmm-windows-update-blocks', 'Windows Updates: Blocked Updates Register', 'Windows updates blocked from installation, with scope (all companies, a company or a single asset), reason and who blocked them.', 'SELECT COALESCE(c.name, ''All companies'') AS company, a.name AS asset, b.kb, b.update_id, b.title, b.reason, TRIM(CONCAT(COALESCE(us.first_name, ''''), '' '', COALESCE(us.last_name, ''''))) AS blocked_by, b.created_at FROM rmm_windows_update_blocks b LEFT JOIN companies c ON c.id = b.company_id LEFT JOIN assets a ON a.id = b.asset_id LEFT JOIN users us ON us.id = b.created_by_user_id ORDER BY b.created_at DESC', 1),
('rmm-patch-policies', 'RMM: Patch Policies', 'Windows Update and Chocolatey patch policies with scope, schedule, next run and last change.', 'SELECT p.name, COALESCE(c.name, ''All companies'') AS company, p.kind, NULLIF(p.package_id, '''') AS package_id, p.cron, p.timezone, CASE WHEN p.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, p.next_run_at, p.revision, p.updated_at FROM rmm_patch_policies p LEFT JOIN companies c ON c.id = p.company_id ORDER BY company, p.name', 1),
('rmm-script-run-outcomes-30-days', 'RMM Scripts: Run Outcomes by Script (Last 30 Days)', 'Script runs in the last 30 days per script with completed, failed, timed-out, expired/cancelled counts, success rate and average duration.', 'SELECT r.script_name, r.language, COUNT(*) AS runs, SUM(CASE WHEN r.status = ''completed'' THEN 1 ELSE 0 END) AS completed, SUM(CASE WHEN r.status = ''failed'' THEN 1 ELSE 0 END) AS failed, SUM(CASE WHEN r.status = ''timed_out'' THEN 1 ELSE 0 END) AS timed_out, SUM(CASE WHEN r.status IN (''expired'', ''cancelled'', ''aborted'') THEN 1 ELSE 0 END) AS expired_or_cancelled, ROUND(100 * SUM(CASE WHEN r.status = ''completed'' THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN r.status IN (''completed'', ''failed'', ''timed_out'') THEN 1 ELSE 0 END), 0), 1) AS success_percent, ROUND(AVG(CASE WHEN r.started_at IS NOT NULL AND r.completed_at IS NOT NULL THEN TIMESTAMPDIFF(SECOND, r.started_at, r.completed_at) END), 0) AS avg_duration_seconds, COUNT(DISTINCT r.agent_id) AS devices, MAX(r.queued_at) AS last_queued_at FROM rmm_script_runs r WHERE r.queued_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY r.script_name, r.language ORDER BY runs DESC', 1),
('rmm-script-runs-failed-last-7-days', 'RMM Scripts: Failed and Timed-Out Runs (Last 7 Days)', 'Script runs that failed or timed out in the last 7 days with device, exit code, error message and how the run was started.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, r.script_name, r.status, r.exit_code, r.error_message, r.run_source, r.run_as, r.queued_at, r.completed_at FROM rmm_script_runs r LEFT JOIN rmm_agents ag ON ag.id = r.agent_id LEFT JOIN companies c ON c.id = r.company_id LEFT JOIN assets a ON a.id = r.asset_id WHERE r.status IN (''failed'', ''timed_out'') AND r.queued_at >= UTC_TIMESTAMP() - INTERVAL 7 DAY ORDER BY r.queued_at DESC', 1),
('rmm-script-runs-by-source-daily', 'RMM Scripts: Daily Run Volume by Source (Last 30 Days)', 'Script runs per day over the last 30 days split by source: manual, schedule, onboarding, patch, ticket, check, event log and result rule.', 'SELECT DATE(r.queued_at) AS day, r.run_source, COUNT(*) AS runs, SUM(CASE WHEN r.status = ''completed'' THEN 1 ELSE 0 END) AS completed, SUM(CASE WHEN r.status IN (''failed'', ''timed_out'') THEN 1 ELSE 0 END) AS failed FROM rmm_script_runs r WHERE r.queued_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY day, r.run_source ORDER BY day, r.run_source', 1),
('rmm-script-runs-by-technician', 'RMM Scripts: Runs by Technician (Last 30 Days)', 'Manually requested script runs per technician in the last 30 days, with the number of scripts, devices and companies touched.', 'SELECT TRIM(CONCAT(COALESCE(us.first_name, ''''), '' '', COALESCE(us.last_name, ''''))) AS technician, us.email, COUNT(*) AS runs, COUNT(DISTINCT r.script_name) AS scripts, COUNT(DISTINCT r.agent_id) AS devices, COUNT(DISTINCT r.company_id) AS companies, SUM(CASE WHEN r.status IN (''failed'', ''timed_out'') THEN 1 ELSE 0 END) AS failed, MAX(r.queued_at) AS last_run_at FROM rmm_script_runs r JOIN users us ON us.id = r.requested_by_user_id WHERE r.queued_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY r.requested_by_user_id, us.first_name, us.last_name, us.email ORDER BY runs DESC', 1),
('rmm-script-runs-in-flight', 'RMM Scripts: Queued and Running for Over an Hour', 'Script runs still queued, dispatched or running more than an hour after they were queued, oldest first.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, r.script_name, r.status, r.run_source, r.queued_at, r.dispatched_at, r.started_at, r.expires_at, TIMESTAMPDIFF(MINUTE, r.queued_at, UTC_TIMESTAMP()) AS minutes_waiting, ag.last_seen_utc FROM rmm_script_runs r LEFT JOIN rmm_agents ag ON ag.id = r.agent_id LEFT JOIN companies c ON c.id = r.company_id LEFT JOIN assets a ON a.id = r.asset_id WHERE r.status IN (''queued'', ''dispatched'', ''running'') AND r.queued_at < UTC_TIMESTAMP() - INTERVAL 1 HOUR ORDER BY r.queued_at ASC', 1),
('rmm-scripts-library-usage', 'RMM Scripts: Library Usage (Last 90 Days)', 'Every active script in the library with its scope, platforms, timeout, run count and last run in the last 90 days; unused scripts are listed first.', 'SELECT s.name, s.folder, s.language, COALESCE(c.name, ''All companies'') AS company, s.platforms_json AS platforms, s.default_timeout_seconds, CASE WHEN s.allow_parallel = 1 THEN ''yes'' ELSE ''no'' END AS allow_parallel, COUNT(r.id) AS runs_90_days, MAX(r.queued_at) AS last_run_at, s.updated_at FROM rmm_scripts s LEFT JOIN companies c ON c.id = s.company_id LEFT JOIN rmm_script_runs r ON r.script_id = s.id AND r.queued_at >= UTC_TIMESTAMP() - INTERVAL 90 DAY WHERE s.is_active = 1 GROUP BY s.id, s.name, s.folder, s.language, c.name, s.platforms_json, s.default_timeout_seconds, s.allow_parallel, s.updated_at ORDER BY runs_90_days ASC, s.folder, s.name', 1),
('rmm-schedules', 'RMM Scripts: Scheduled Script Overview', 'Scheduled scripts with scope, cron, run-as account, next and last run and the last run summary.', 'SELECT sch.name, COALESCE(c.name, ''All companies'') AS company, s.name AS script, sch.cron, sch.timezone, sch.target_mode, sch.run_as, CASE WHEN sch.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, sch.next_run_at, sch.last_run_at, sch.last_run_summary FROM rmm_schedules sch LEFT JOIN rmm_scripts s ON s.id = sch.script_id LEFT JOIN companies c ON c.id = sch.company_id ORDER BY state DESC, sch.next_run_at', 1),
('rmm-ticket-script-runs', 'RMM Scripts: Runs Triggered From Tickets (Last 30 Days)', 'Script runs launched by the ticket automation action in the last 30 days, with the ticket, result and when it was reported back.', 'SELECT t.ticket_number, t.subject, c.name AS company, r.script_name, r.status, r.exit_code, tsr.success_status, tsr.created_at, tsr.reported_at FROM rmm_ticket_script_runs tsr JOIN rmm_script_runs r ON r.id = tsr.run_id LEFT JOIN tickets t ON t.id = tsr.ticket_id LEFT JOIN companies c ON c.id = r.company_id WHERE tsr.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY tsr.created_at DESC', 1),
('rmm-remote-sessions-30-days', 'RMM: Remote Control Sessions (Last 30 Days)', 'Remote control sessions in the last 30 days per technician and provider, with how many became ready and the average time to connect.', 'SELECT TRIM(CONCAT(COALESCE(us.first_name, ''''), '' '', COALESCE(us.last_name, ''''))) AS technician, rs.provider, rs.mode, COUNT(*) AS sessions, SUM(CASE WHEN rs.ready_at IS NOT NULL THEN 1 ELSE 0 END) AS connected, SUM(CASE WHEN rs.status = ''failed'' THEN 1 ELSE 0 END) AS failed, ROUND(AVG(CASE WHEN rs.ready_at IS NOT NULL THEN TIMESTAMPDIFF(SECOND, rs.created_at, rs.ready_at) END), 0) AS avg_seconds_to_ready, COUNT(DISTINCT rs.asset_id) AS devices, COUNT(DISTINCT rs.company_id) AS companies FROM rmm_remote_sessions rs LEFT JOIN users us ON us.id = rs.requested_by_user_id WHERE rs.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY rs.requested_by_user_id, us.first_name, us.last_name, rs.provider, rs.mode ORDER BY sessions DESC', 1),
('rmm-onboarding-runs-30-days', 'RMM: Device Onboarding Runs (Last 30 Days)', 'Automatic device onboarding runs in the last 30 days per company: completed, failed and still running, with failed steps and average duration.', 'SELECT c.name AS company, COUNT(*) AS runs, SUM(CASE WHEN o.status = ''completed'' THEN 1 ELSE 0 END) AS completed, SUM(CASE WHEN o.status = ''failed'' THEN 1 ELSE 0 END) AS failed, SUM(CASE WHEN o.status = ''running'' THEN 1 ELSE 0 END) AS running, SUM(o.failed_steps) AS failed_steps, ROUND(AVG(CASE WHEN o.completed_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, o.started_at, o.completed_at) END), 0) AS avg_minutes, MAX(o.started_at) AS last_started_at FROM rmm_onboarding_runs o LEFT JOIN companies c ON c.id = o.company_id WHERE o.started_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY o.company_id, c.name ORDER BY runs DESC', 1),
('rmm-onboarding-steps-by-company', 'RMM: Onboarding Steps by Company', 'Configured device onboarding steps per company in order, with the script or package step, run-as account and failure handling.', 'SELECT c.name AS company, st.position, COALESCE(s.name, ''Chocolatey packages'') AS step, st.package_ids_json AS packages, st.target_mode, st.run_as, st.timeout_seconds, CASE WHEN st.continue_on_failure = 1 THEN ''continue'' ELSE ''stop'' END AS on_failure, st.skip_existing_before FROM rmm_onboarding_steps st LEFT JOIN rmm_scripts s ON s.id = st.script_id LEFT JOIN companies c ON c.id = st.company_id ORDER BY company, st.position', 1),
('rmm-checks-failing-now', 'RMM Checks: Devices Currently Failing or Warning', 'Check results currently failing or warning, with the value seen, how long the problem has lasted and any linked ticket.', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, ch.name AS check_name, ch.check_type, ch.target, st.status, st.value_text, st.problem_since, TIMESTAMPDIFF(HOUR, st.problem_since, UTC_TIMESTAMP()) AS hours_in_problem, st.checked_at, t.ticket_number, t.status AS ticket_status FROM rmm_check_states st JOIN rmm_checks ch ON ch.id = st.check_id JOIN rmm_agents ag ON ag.id = st.agent_id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id LEFT JOIN tickets t ON t.id = st.ticket_id WHERE ag.status = ''active'' AND ch.is_enabled = 1 AND st.status IN (''failing'', ''warning'') ORDER BY st.status, st.problem_since ASC', 1),
('rmm-check-health-by-check', 'RMM Checks: Result Summary by Check', 'Every RMM check with passing, problem, failing and waiting device counts and the last time it failed.', 'SELECT ch.name AS check_name, ch.check_type, ch.target, COALESCE(c.name, ''All companies'') AS company, ch.action, CASE WHEN ch.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, COUNT(st.agent_id) AS devices, SUM(CASE WHEN st.status = ''passing'' THEN 1 ELSE 0 END) AS passing, SUM(CASE WHEN st.status = ''warning'' THEN 1 ELSE 0 END) AS warning, SUM(CASE WHEN st.status = ''failing'' THEN 1 ELSE 0 END) AS failing, SUM(CASE WHEN st.status = ''pending'' THEN 1 ELSE 0 END) AS pending, ch.last_failed_at FROM rmm_checks ch LEFT JOIN rmm_check_states st ON st.check_id = ch.id LEFT JOIN companies c ON c.id = ch.company_id GROUP BY ch.id, ch.name, ch.check_type, ch.target, c.name, ch.action, ch.is_enabled, ch.last_failed_at ORDER BY failing DESC, warning DESC, ch.name', 1),
('rmm-checks-by-company', 'RMM Checks: Problems by Company', 'Check results per company for active agents: passing, warning and failing counts and devices with at least one problem.', 'SELECT c.name AS company, COUNT(*) AS results, SUM(CASE WHEN st.status = ''passing'' THEN 1 ELSE 0 END) AS passing, SUM(CASE WHEN st.status = ''warning'' THEN 1 ELSE 0 END) AS warning, SUM(CASE WHEN st.status = ''failing'' THEN 1 ELSE 0 END) AS failing, COUNT(DISTINCT CASE WHEN st.status IN (''warning'', ''failing'') THEN st.agent_id END) AS devices_with_problems FROM rmm_check_states st JOIN rmm_checks ch ON ch.id = st.check_id JOIN rmm_agents ag ON ag.id = st.agent_id LEFT JOIN companies c ON c.id = ag.company_id WHERE ag.status = ''active'' AND ch.is_enabled = 1 GROUP BY ag.company_id, c.name ORDER BY failing DESC, warning DESC', 1),
('rmm-event-log-rules-activity', 'RMM: Event Log Rule Activity', 'Event log rules with scope, action, match count, last match, devices triggered and open tickets they raised.', 'SELECT r.name, COALESCE(c.name, ''All companies'') AS company, r.action, CASE WHEN r.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, r.match_count, r.last_matched_at, r.cooldown_minutes, (SELECT COUNT(*) FROM rmm_event_log_rule_triggers tr WHERE tr.rule_id = r.id) AS devices_triggered, (SELECT COUNT(*) FROM rmm_event_log_rule_tickets rt JOIN tickets t ON t.id = rt.ticket_id WHERE rt.rule_id = r.id AND t.status NOT IN (''resolved'', ''closed'')) AS open_tickets, r.last_run_summary FROM rmm_event_log_rules r LEFT JOIN companies c ON c.id = r.company_id ORDER BY r.match_count DESC, r.name', 1),
('rmm-script-result-rules-activity', 'RMM: Script Result Rule Activity', 'Script result rules with the script they watch, the action taken, match count, last match and open tickets they raised.', 'SELECT r.name, COALESCE(c.name, ''All companies'') AS company, COALESCE(s.name, ''Any script'') AS watched_script, r.action, ns.name AS next_script, CASE WHEN r.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, r.match_count, r.last_matched_at, (SELECT COUNT(*) FROM rmm_script_result_rule_tickets rt JOIN tickets t ON t.id = rt.ticket_id WHERE rt.rule_id = r.id AND t.status NOT IN (''resolved'', ''closed'')) AS open_tickets, r.last_run_summary FROM rmm_script_result_rules r LEFT JOIN companies c ON c.id = r.company_id LEFT JOIN rmm_scripts s ON s.id = r.script_id LEFT JOIN rmm_scripts ns ON ns.id = r.next_script_id ORDER BY r.match_count DESC, r.name', 1),
('rmm-automation-open-tickets', 'RMM: Open Tickets Raised by Automation', 'Open tickets raised by RMM checks, event log rules, script result rules and health check detections, with the rule or detection that raised them.', 'SELECT x.origin, x.rule_name, t.ticket_number, t.subject, c.name AS company, t.status, t.priority, t.created_at FROM ( SELECT ''RMM check'' AS origin, ch.name AS rule_name, st.ticket_id FROM rmm_check_states st JOIN rmm_checks ch ON ch.id = st.check_id WHERE st.ticket_id IS NOT NULL UNION ALL SELECT ''Event log rule'', r.name, rt.ticket_id FROM rmm_event_log_rule_tickets rt JOIN rmm_event_log_rules r ON r.id = rt.rule_id UNION ALL SELECT ''Script result rule'', r.name, rt.ticket_id FROM rmm_script_result_rule_tickets rt JOIN rmm_script_result_rules r ON r.id = rt.rule_id UNION ALL SELECT ''Health check detection'', d.detection_key, d.ticket_id FROM ai_health_check_detection_tickets d ) x JOIN tickets t ON t.id = x.ticket_id LEFT JOIN companies c ON c.id = t.company_id WHERE t.status NOT IN (''resolved'', ''closed'') ORDER BY t.created_at DESC', 1),
('rmm-findings-open', 'RMM Findings: Open Findings by Severity', 'Active RMM findings that are open or acknowledged, most severe first, with category, occurrences and first and last seen.', 'SELECT f.severity, f.category, f.title, f.status, f.source, f.occurrences, f.confidence, f.first_seen_at, f.last_seen_at, f.recommendation FROM rmm_findings f WHERE f.is_active = 1 AND f.status IN (''open'', ''acknowledged'') ORDER BY FIELD(f.severity, ''critical'', ''high'', ''medium'', ''low'', ''info''), f.last_seen_at DESC', 1),
('rmm-findings-by-category', 'RMM Findings: Summary by Category and Severity', 'Active RMM findings grouped by category and severity with open, acknowledged and dismissed counts.', 'SELECT f.category, f.severity, COUNT(*) AS findings, SUM(CASE WHEN f.status = ''open'' THEN 1 ELSE 0 END) AS open, SUM(CASE WHEN f.status = ''acknowledged'' THEN 1 ELSE 0 END) AS acknowledged, SUM(CASE WHEN f.status = ''dismissed'' THEN 1 ELSE 0 END) AS dismissed, SUM(f.occurrences) AS occurrences, MAX(f.last_seen_at) AS last_seen_at FROM rmm_findings f WHERE f.is_active = 1 GROUP BY f.category, f.severity ORDER BY f.category, FIELD(f.severity, ''critical'', ''high'', ''medium'', ''low'', ''info'')', 1),
('rmm-finding-runs', 'RMM Findings: Analysis Run History (Last 30 Days)', 'RMM Findings analysis runs in the last 30 days with trigger, status, AI analysis status and model, findings produced and duration.', 'SELECT fr.id AS run_id, fr.trigger_source, fr.status, fr.ai_status, fr.ai_model, fr.finding_count, fr.started_at, fr.finished_at, TIMESTAMPDIFF(SECOND, fr.started_at, fr.finished_at) AS duration_seconds, COALESCE(fr.error, fr.ai_error) AS error FROM rmm_finding_runs fr WHERE fr.started_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY fr.started_at DESC', 1),
('health-checks-latest-by-asset', 'Health Checks: Latest Result per Device', 'The most recent completed AI health check for each device with overall status, health score, platform and summary, worst first.', 'SELECT c.name AS company, a.name AS device, h.overall_status, h.health_score, h.platform, h.run_source, h.completed_at, h.summary FROM ai_health_checks h JOIN (SELECT asset_id, MAX(id) AS id FROM ai_health_checks WHERE status = ''completed'' GROUP BY asset_id) latest ON latest.id = h.id LEFT JOIN companies c ON c.id = h.company_id LEFT JOIN assets a ON a.id = h.asset_id ORDER BY FIELD(h.overall_status, ''critical'', ''attention'', ''healthy''), h.health_score ASC', 1),
('health-checks-score-by-company', 'Health Checks: Device Health by Company', 'Per company, the latest completed health check per device summarised as average score and healthy, attention and critical device counts.', 'SELECT c.name AS company, COUNT(*) AS devices, ROUND(AVG(h.health_score), 0) AS avg_health_score, MIN(h.health_score) AS lowest_score, SUM(CASE WHEN h.overall_status = ''healthy'' THEN 1 ELSE 0 END) AS healthy, SUM(CASE WHEN h.overall_status = ''attention'' THEN 1 ELSE 0 END) AS attention, SUM(CASE WHEN h.overall_status = ''critical'' THEN 1 ELSE 0 END) AS critical, MAX(h.completed_at) AS last_check_at FROM ai_health_checks h JOIN (SELECT asset_id, MAX(id) AS id FROM ai_health_checks WHERE status = ''completed'' GROUP BY asset_id) latest ON latest.id = h.id LEFT JOIN companies c ON c.id = h.company_id GROUP BY h.company_id, c.name ORDER BY avg_health_score ASC', 1),
('health-checks-monthly-trend', 'Health Checks: Monthly Score Trend', 'Completed health checks per month over the last 12 months with average score and the share of healthy, attention and critical results.', 'SELECT DATE_FORMAT(h.completed_at, ''%Y-%m'') AS month, COUNT(*) AS checks, COUNT(DISTINCT h.asset_id) AS devices, ROUND(AVG(h.health_score), 1) AS avg_health_score, SUM(CASE WHEN h.overall_status = ''healthy'' THEN 1 ELSE 0 END) AS healthy, SUM(CASE WHEN h.overall_status = ''attention'' THEN 1 ELSE 0 END) AS attention, SUM(CASE WHEN h.overall_status = ''critical'' THEN 1 ELSE 0 END) AS critical FROM ai_health_checks h WHERE h.status = ''completed'' AND h.completed_at >= UTC_TIMESTAMP() - INTERVAL 12 MONTH GROUP BY month ORDER BY month', 1),
('health-checks-run-outcomes-30-days', 'Health Checks: Run Outcomes (Last 30 Days)', 'Health check runs in the last 30 days by source (manual, schedule, ticket) and status, with average time to complete.', 'SELECT h.run_source, h.status, COUNT(*) AS runs, COUNT(DISTINCT h.asset_id) AS devices, ROUND(AVG(CASE WHEN h.completed_at IS NOT NULL THEN TIMESTAMPDIFF(SECOND, h.created_at, h.completed_at) END), 0) AS avg_seconds_to_complete, MAX(h.created_at) AS last_run_at FROM ai_health_checks h WHERE h.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY h.run_source, h.status ORDER BY h.run_source, runs DESC', 1),
('health-checks-failed-runs', 'Health Checks: Failed Runs (Last 30 Days)', 'Health check runs that failed in the last 30 days with the device, last stage reached and error.', 'SELECT c.name AS company, a.name AS device, h.platform, h.run_source, h.stage_message, h.error, h.created_at FROM ai_health_checks h LEFT JOIN companies c ON c.id = h.company_id LEFT JOIN assets a ON a.id = h.asset_id WHERE h.status = ''failed'' AND h.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY h.created_at DESC', 1),
('health-check-schedules', 'Health Checks: Monthly Schedule Status', 'Scheduled monthly health checks per device with the next window, last start and result, flagging windows that ended without a run.', 'SELECT c.name AS company, a.name AS device, s.next_run_at, s.window_ends_at, s.last_started_at, s.last_result, CASE WHEN s.window_ends_at < UTC_TIMESTAMP() AND (s.last_started_at IS NULL OR s.last_started_at < s.next_run_at) THEN ''missed'' ELSE ''ok'' END AS window_state FROM ai_health_check_schedules s LEFT JOIN companies c ON c.id = s.company_id LEFT JOIN assets a ON a.id = s.asset_id ORDER BY window_state, s.next_run_at', 1),
('health-check-detection-tickets', 'Health Checks: Tickets by Detection', 'Tickets raised by health check detections grouped by detection, with open and total ticket counts and devices affected.', 'SELECT d.detection_key, COUNT(*) AS tickets, SUM(CASE WHEN t.status NOT IN (''resolved'', ''closed'') THEN 1 ELSE 0 END) AS open_tickets, COUNT(DISTINCT d.asset_id) AS devices, COUNT(DISTINCT t.company_id) AS companies, MAX(d.updated_at) AS last_raised_at FROM ai_health_check_detection_tickets d JOIN tickets t ON t.id = d.ticket_id GROUP BY d.detection_key ORDER BY open_tickets DESC, tickets DESC', 1),
('health-check-remediations', 'Health Checks: Remediation Activity', 'Automatic remediations configured for health check detections with scope, script, ticket option, run count and last result.', 'SELECT r.detection_key, COALESCE(c.name, ''All companies'') AS company, s.name AS script, CASE WHEN r.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, CASE WHEN r.create_ticket = 1 THEN ''yes'' ELSE ''no'' END AS creates_ticket, r.run_count, r.last_run_at, r.last_summary FROM ai_health_check_remediations r LEFT JOIN companies c ON c.id = r.company_id LEFT JOIN rmm_scripts s ON s.id = r.script_id ORDER BY r.run_count DESC, r.detection_key', 1),
('health-check-required-logs-open', 'Health Checks: Open Required Logs', 'Logs the AI health check and troubleshooter asked for but could not read, still open for review, most frequent first.', 'SELECT l.platform, l.kind, l.source, l.reason_code, l.reason, l.features, l.occurrences, l.first_seen_at, l.last_seen_at, c.name AS last_company, a.name AS last_device FROM ai_required_logs l LEFT JOIN companies c ON c.id = l.last_company_id LEFT JOIN assets a ON a.id = l.last_asset_id WHERE l.status = ''open'' ORDER BY l.occurrences DESC, l.last_seen_at DESC', 1),
('health-check-groups', 'Health Checks: Device Rule Groups', 'Health check device-rule groups with scope, whether they are enabled or the default, and when they last changed.', 'SELECT g.name, COALESCE(c.name, ''All companies'') AS company, CASE WHEN g.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, CASE WHEN g.is_default = 1 THEN ''yes'' ELSE ''no'' END AS is_default, g.target_rules_json AS target_rules, g.updated_at FROM ai_health_check_groups g LEFT JOIN companies c ON c.id = g.company_id ORDER BY company, g.name', 1),
('tray-devices-by-version', 'Tray: Devices by App Version and Platform', 'Active tray devices by platform and app version with how many checked in within the last day.', 'SELECT COALESCE(td.os, ''unknown'') AS platform, COALESCE(td.agent_version, ''unknown'') AS tray_version, COUNT(*) AS devices, SUM(CASE WHEN td.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 1 DAY THEN 1 ELSE 0 END) AS seen_last_24_hours, COUNT(DISTINCT td.company_id) AS companies FROM tray_devices td WHERE td.status = ''active'' GROUP BY td.os, td.agent_version ORDER BY platform, devices DESC', 1),
('tray-devices-not-seen-30-days', 'Tray: Devices Not Seen in 30 Days', 'Active tray devices that have not checked in for over 30 days, with the last user, IP and version.', 'SELECT c.name AS company, td.hostname, td.os, td.os_version, td.agent_version, td.console_user, td.last_ip, td.last_seen_utc, TIMESTAMPDIFF(DAY, td.last_seen_utc, UTC_TIMESTAMP()) AS days_since_seen FROM tray_devices td LEFT JOIN companies c ON c.id = td.company_id WHERE td.status = ''active'' AND (td.last_seen_utc IS NULL OR td.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 30 DAY) ORDER BY td.last_seen_utc ASC', 1),
('tray-enrolments-by-month', 'Tray: Device Enrolments by Month', 'Tray devices enrolled per month over the last 12 months by platform.', 'SELECT DATE_FORMAT(td.created_at, ''%Y-%m'') AS month, SUM(CASE WHEN td.os = ''windows'' THEN 1 ELSE 0 END) AS windows, SUM(CASE WHEN td.os = ''darwin'' THEN 1 ELSE 0 END) AS macos, SUM(CASE WHEN td.os NOT IN (''windows'', ''darwin'') OR td.os IS NULL THEN 1 ELSE 0 END) AS other, COUNT(*) AS enrolments FROM tray_devices td WHERE td.created_at >= UTC_TIMESTAMP() - INTERVAL 12 MONTH GROUP BY month ORDER BY month', 1),
('tray-deployment-links', 'Tray: Deployment URL Usage', 'Tray deployment URLs per company with downloads, last download, expiry, revocation and the latest installer build status.', 'SELECT c.name AS company, l.label, l.download_count, l.last_downloaded_at, l.created_at, l.expires_at, l.revoked_at, CASE WHEN l.revoked_at IS NOT NULL THEN ''revoked'' WHEN l.expires_at IS NOT NULL AND l.expires_at < UTC_TIMESTAMP() THEN ''expired'' ELSE ''active'' END AS state, (SELECT b.status FROM tray_deployment_builds b WHERE b.deployment_link_id = l.id ORDER BY b.requested_at DESC, b.id DESC LIMIT 1) AS latest_build_status, (SELECT b.release_tag FROM tray_deployment_builds b WHERE b.deployment_link_id = l.id ORDER BY b.requested_at DESC, b.id DESC LIMIT 1) AS latest_build_release FROM tray_deployment_links l LEFT JOIN companies c ON c.id = l.company_id ORDER BY state, company', 1),
('tray-deployment-builds-failed', 'Tray: Failed Installer Builds (Last 30 Days)', 'Tray deployment installer builds that failed in the last 30 days with the company, release and error.', 'SELECT c.name AS company, l.label, b.release_tag, b.status, b.error, b.requested_at, b.completed_at FROM tray_deployment_builds b JOIN tray_deployment_links l ON l.id = b.deployment_link_id LEFT JOIN companies c ON c.id = l.company_id WHERE b.status = ''failed'' AND b.requested_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY b.requested_at DESC', 1),
('assets-warranty-expiring-next-90-days', 'Assets: Warranties Expiring in the Next 90 Days', 'Active assets whose warranty ends in the next 90 days, with the warranty source and when it was last looked up.', 'SELECT c.name AS company, a.name AS asset, a.asset_type, a.serial_number, a.warranty_start_date, a.warranty_end_date, DATEDIFF(a.warranty_end_date, CURRENT_DATE) AS days_remaining, a.warranty_status, a.warranty_source, a.warranty_checked_at FROM assets a LEFT JOIN companies c ON c.id = a.company_id WHERE a.archived_at IS NULL AND a.warranty_end_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL 90 DAY ORDER BY a.warranty_end_date ASC', 1),
('assets-out-of-warranty', 'Assets: Out of Warranty', 'Active assets whose warranty has already ended, longest expired first.', 'SELECT c.name AS company, a.name AS asset, a.asset_type, a.serial_number, a.warranty_end_date, DATEDIFF(CURRENT_DATE, a.warranty_end_date) AS days_expired, a.warranty_source, a.last_sync FROM assets a LEFT JOIN companies c ON c.id = a.company_id WHERE a.archived_at IS NULL AND a.warranty_end_date < CURRENT_DATE ORDER BY a.warranty_end_date ASC', 1),
('assets-warranty-lookup-status', 'Assets: Warranty Lookup Coverage by Company', 'Per company, active assets with a warranty found, not found, unsupported, errored or never looked up.', 'SELECT c.name AS company, COUNT(*) AS assets, SUM(CASE WHEN a.warranty_lookup_status = ''found'' THEN 1 ELSE 0 END) AS found, SUM(CASE WHEN a.warranty_lookup_status = ''not_found'' THEN 1 ELSE 0 END) AS not_found, SUM(CASE WHEN a.warranty_lookup_status = ''unsupported'' THEN 1 ELSE 0 END) AS unsupported, SUM(CASE WHEN a.warranty_lookup_status = ''error'' THEN 1 ELSE 0 END) AS errors, SUM(CASE WHEN a.warranty_lookup_status IS NULL THEN 1 ELSE 0 END) AS never_checked, MAX(a.warranty_checked_at) AS last_checked_at FROM assets a LEFT JOIN companies c ON c.id = a.company_id WHERE a.archived_at IS NULL GROUP BY a.company_id, c.name ORDER BY company', 1),
('assets-by-asset-type', 'Assets: Count by Asset Type and Company', 'Active assets per company and asset type (as used by the network map and rack views), with how many were classified automatically.', 'SELECT c.name AS company, COALESCE(a.asset_type, ''unclassified'') AS asset_type, COUNT(*) AS assets, SUM(CASE WHEN a.asset_type_source = ''auto'' THEN 1 ELSE 0 END) AS auto_classified FROM assets a LEFT JOIN companies c ON c.id = a.company_id WHERE a.archived_at IS NULL GROUP BY a.company_id, c.name, a.asset_type ORDER BY company, assets DESC', 1),
('assets-by-tag', 'Assets: Count by Tag', 'Tags with the number of active assets carrying them, split into manually applied and automatically applied.', 'SELECT tg.name AS tag, tg.slug, COUNT(at.asset_id) AS assets, SUM(CASE WHEN at.source = ''manual'' THEN 1 ELSE 0 END) AS manual, SUM(CASE WHEN at.source <> ''manual'' THEN 1 ELSE 0 END) AS automatic, COUNT(DISTINCT a.company_id) AS companies FROM tags tg LEFT JOIN asset_tags at ON at.tag_id = tg.id LEFT JOIN assets a ON a.id = at.asset_id AND a.archived_at IS NULL GROUP BY tg.id, tg.name, tg.slug ORDER BY assets DESC, tg.name', 1),
('assets-without-rmm-agent', 'Assets: Workstations and Servers Without RMM', 'Active assets classified as workstations, laptops, thin clients, servers, hypervisors or virtual machines that have no active RMM agent.', 'SELECT c.name AS company, a.name AS asset, a.asset_type, a.os_name, a.last_user, a.last_sync FROM assets a LEFT JOIN companies c ON c.id = a.company_id WHERE a.archived_at IS NULL AND a.asset_type IN (''workstation'', ''laptop'', ''thin_client'', ''server'', ''hypervisor'', ''virtual_machine'') AND NOT EXISTS (SELECT 1 FROM rmm_agents ag WHERE ag.asset_id = a.id AND ag.status = ''active'') ORDER BY company, asset', 1),
('network-map-documentation-coverage', 'Network Map: Documentation Coverage by Company', 'Per company, documented network interfaces and links by medium (copper, fibre, wireless and other), to show which sites have a mapped network.', 'SELECT c.name AS company, (SELECT COUNT(*) FROM asset_interfaces i WHERE i.company_id = c.id) AS interfaces, (SELECT COUNT(DISTINCT i.asset_id) FROM asset_interfaces i WHERE i.company_id = c.id) AS assets_with_interfaces, (SELECT COUNT(*) FROM network_links l WHERE l.company_id = c.id) AS links, (SELECT COUNT(*) FROM network_links l WHERE l.company_id = c.id AND l.medium = ''copper'') AS copper_links, (SELECT COUNT(*) FROM network_links l WHERE l.company_id = c.id AND l.medium = ''fibre'') AS fibre_links, (SELECT COUNT(*) FROM network_links l WHERE l.company_id = c.id AND l.medium IN (''wireless'', ''radio'')) AS wireless_links, (SELECT COUNT(*) FROM network_links l WHERE l.company_id = c.id AND l.medium NOT IN (''copper'', ''fibre'', ''wireless'', ''radio'')) AS other_links FROM companies c WHERE c.archived = 0 ORDER BY links DESC, company', 1),
('llm-usage-by-feature-30-days', 'AI Usage: Requests and Tokens by Feature (Last 30 Days)', 'LLM requests in the last 30 days per feature and model with error count, input and output tokens (input_tok, output_tok) and average latency.', 'SELECT u.feature, COALESCE(u.model, ''unknown'') AS model, COUNT(*) AS requests, SUM(CASE WHEN u.status IN (''error'', ''failed'') THEN 1 ELSE 0 END) AS failed, SUM(u.input_tokens) AS input_tok, SUM(u.output_tokens) AS output_tok, SUM(u.tokens_estimated) AS estimated_requests, ROUND(AVG(u.duration_ms), 0) AS avg_duration_ms FROM llm_usage_events u WHERE u.occurred_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY u.feature, u.model ORDER BY SUM(u.input_tokens + u.output_tokens) DESC', 1),
('llm-usage-daily', 'AI Usage: Daily Requests and Tokens (Last 30 Days)', 'LLM requests, failures and input and output tokens (input_tok, output_tok) per day for the last 30 days.', 'SELECT DATE(u.occurred_at) AS day, COUNT(*) AS requests, SUM(CASE WHEN u.status IN (''error'', ''failed'') THEN 1 ELSE 0 END) AS failed, SUM(u.input_tokens) AS input_tok, SUM(u.output_tokens) AS output_tok, ROUND(AVG(u.duration_ms), 0) AS avg_duration_ms FROM llm_usage_events u WHERE u.occurred_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY day ORDER BY day', 1),
('llm-usage-errors-7-days', 'AI Usage: Failed Requests by Feature (Last 7 Days)', 'LLM requests that errored or failed in the last 7 days per feature, provider and model with the last failure time.', 'SELECT u.feature, u.provider, u.model, u.status, COUNT(*) AS failures, MAX(u.occurred_at) AS last_failure_at FROM llm_usage_events u WHERE u.status IN (''error'', ''failed'') AND u.occurred_at >= UTC_TIMESTAMP() - INTERVAL 7 DAY GROUP BY u.feature, u.provider, u.model, u.status ORDER BY failures DESC', 1),
('user-feedback-summary', 'Feedback: Ratings by Page (Last 90 Days)', 'Thumbs up and down feedback in the last 90 days grouped by page, with the satisfaction percentage.', 'SELECT COALESCE(SUBSTRING_INDEX(f.page_url, ''?'', 1), ''unknown'') AS page, COUNT(*) AS responses, SUM(CASE WHEN f.rating = ''up'' THEN 1 ELSE 0 END) AS thumbs_up, SUM(CASE WHEN f.rating = ''down'' THEN 1 ELSE 0 END) AS thumbs_down, ROUND(100 * SUM(CASE WHEN f.rating = ''up'' THEN 1 ELSE 0 END) / COUNT(*), 0) AS satisfaction_percent, MAX(f.created_at) AS last_feedback_at FROM user_feedback f WHERE f.created_at >= UTC_TIMESTAMP() - INTERVAL 90 DAY GROUP BY page ORDER BY thumbs_down DESC, responses DESC', 1),
('user-feedback-negative-recent', 'Feedback: Recent Negative Feedback', 'Thumbs-down feedback from the last 30 days with the reason, suggested improvement, page and linked ticket.', 'SELECT f.created_at, us.email AS user_email, f.page_url, f.reason, f.suggested_improvements, t.ticket_number FROM user_feedback f LEFT JOIN users us ON us.id = f.user_id LEFT JOIN tickets t ON t.id = f.ticket_id WHERE f.rating = ''down'' AND f.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY f.created_at DESC', 1),
('rag-relationship-feedback-summary', 'AI Quality: Related-Item Feedback by Type', 'Technician ratings of AI related-item suggestions grouped by relationship and target type, with the helpful percentage and average scores.', 'SELECT COALESCE(fb.relationship_type, ''unknown'') AS relationship_type, COALESCE(fb.target_source_type, ''unknown'') AS target_type, COUNT(*) AS ratings, SUM(CASE WHEN fb.rating = ''up'' THEN 1 ELSE 0 END) AS helpful, SUM(CASE WHEN fb.rating = ''down'' THEN 1 ELSE 0 END) AS not_helpful, ROUND(100 * SUM(CASE WHEN fb.rating = ''up'' THEN 1 ELSE 0 END) / COUNT(*), 0) AS helpful_percent, ROUND(AVG(fb.relevance_score), 3) AS avg_relevance, ROUND(AVG(fb.confidence), 3) AS avg_confidence FROM rag_relationship_feedback fb GROUP BY fb.relationship_type, fb.target_source_type ORDER BY ratings DESC', 1),
('agent-conversations-by-user-30-days', 'AI Agent: Conversations by User (Last 30 Days)', 'AI agent conversations started in the last 30 days per user, with total turns and the last conversation time.', 'SELECT us.email AS user_email, TRIM(CONCAT(COALESCE(us.first_name, ''''), '' '', COALESCE(us.last_name, ''''))) AS user_name, COUNT(DISTINCT ac.id) AS conversations, COUNT(t.id) AS turns, MAX(ac.updated_at) AS last_activity_at FROM agent_conversations ac JOIN users us ON us.id = ac.user_id LEFT JOIN agent_conversation_turns t ON t.conversation_id = ac.id WHERE ac.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY ac.user_id, us.email, us.first_name, us.last_name ORDER BY conversations DESC', 1),
('users-ai-opt-out-and-policy-acceptance', 'Users: AI Opt-Out and Policy Acceptance by Company', 'Active users per company with how many opted out of AI features, accepted the legal policies, or have never accepted them.', 'SELECT COALESCE(c.name, ''No company'') AS company, COUNT(*) AS users, SUM(us.ai_opt_out) AS ai_opted_out, SUM(CASE WHEN us.policies_accepted_at IS NOT NULL THEN 1 ELSE 0 END) AS policies_accepted, SUM(CASE WHEN us.policies_accepted_at IS NULL THEN 1 ELSE 0 END) AS policies_not_accepted, MAX(us.policies_accepted_version) AS latest_version_accepted FROM users us LEFT JOIN companies c ON c.id = us.company_id WHERE us.is_active = 1 GROUP BY us.company_id, c.name ORDER BY company', 1),
('account-anonymisation-requests', 'Users: Account Anonymisation Requests', 'Account anonymisation (right to erasure) requests with status, who decided, when executed and the support ticket.', 'SELECT r.id AS request_id, r.status, r.requested_at, r.scheduled_for, r.decided_at, TRIM(CONCAT(COALESCE(d.first_name, ''''), '' '', COALESCE(d.last_name, ''''))) AS decided_by, r.executed_at, r.completed_at, t.ticket_number AS support_ticket, r.error_message FROM account_anonymisation_requests r LEFT JOIN users d ON d.id = r.decided_by LEFT JOIN tickets t ON t.id = r.support_ticket_id ORDER BY FIELD(r.status, ''pending'', ''approved'', ''rejected'', ''completed''), r.requested_at DESC', 1),
('marketing-campaign-performance', 'Marketing: Campaign Performance', 'Marketing campaigns with recipients, sent, delivered, opened, clicked, bounced, skipped and replied counts, plus open, click and reply rates.', 'SELECT mc.name, mc.category, mc.status, mc.scheduled_for, mc.completed_at, COUNT(r.id) AS recipients, SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END) AS sent, SUM(CASE WHEN r.delivered_at IS NOT NULL THEN 1 ELSE 0 END) AS delivered, SUM(CASE WHEN r.first_opened_at IS NOT NULL THEN 1 ELSE 0 END) AS opened, SUM(CASE WHEN r.first_clicked_at IS NOT NULL THEN 1 ELSE 0 END) AS clicked, SUM(CASE WHEN r.bounced_at IS NOT NULL THEN 1 ELSE 0 END) AS bounced, SUM(CASE WHEN r.status = ''skipped'' THEN 1 ELSE 0 END) AS skipped, SUM(CASE WHEN r.replied_at IS NOT NULL THEN 1 ELSE 0 END) AS replied, ROUND(100 * SUM(CASE WHEN r.first_opened_at IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END), 0), 1) AS open_rate_percent, ROUND(100 * SUM(CASE WHEN r.first_clicked_at IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END), 0), 1) AS click_rate_percent, ROUND(100 * SUM(CASE WHEN r.replied_at IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END), 0), 1) AS reply_rate_percent FROM marketing_campaigns mc LEFT JOIN marketing_campaign_recipients r ON r.campaign_id = mc.id GROUP BY mc.id, mc.name, mc.category, mc.status, mc.scheduled_for, mc.completed_at ORDER BY COALESCE(mc.completed_at, mc.scheduled_for, mc.created_at) DESC', 1),
('marketing-campaign-engagement-by-company', 'Marketing: Campaign Engagement by Company', 'Marketing email engagement per recipient company across all campaigns: emails sent, opened, clicked, replied and bounced.', 'SELECT COALESCE(c.name, ''No company'') AS company, COUNT(*) AS emails, SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END) AS sent, SUM(CASE WHEN r.first_opened_at IS NOT NULL THEN 1 ELSE 0 END) AS opened, SUM(CASE WHEN r.first_clicked_at IS NOT NULL THEN 1 ELSE 0 END) AS clicked, SUM(CASE WHEN r.replied_at IS NOT NULL THEN 1 ELSE 0 END) AS replied, SUM(CASE WHEN r.bounced_at IS NOT NULL THEN 1 ELSE 0 END) AS bounced, COUNT(DISTINCT r.campaign_id) AS campaigns FROM marketing_campaign_recipients r LEFT JOIN companies c ON c.id = r.company_id GROUP BY r.company_id, c.name ORDER BY opened DESC, emails DESC', 1),
('marketing-bounces-and-skips', 'Marketing: Bounced and Skipped Recipients', 'Campaign recipients that bounced, failed or were skipped, with the skip reason or error, to clean up contact data.', 'SELECT mc.name AS campaign, COALESCE(c.name, ''No company'') AS company, r.email, r.name, r.status, r.skip_reason, r.error_message, r.bounced_at, r.updated_at FROM marketing_campaign_recipients r JOIN marketing_campaigns mc ON mc.id = r.campaign_id LEFT JOIN companies c ON c.id = r.company_id WHERE r.bounced_at IS NOT NULL OR r.status IN (''skipped'', ''failed'') ORDER BY r.updated_at DESC', 1),
('marketing-opt-outs-by-month', 'Marketing: Email Opt-Outs by Month and Category', 'Marketing email opt-outs per month and category over the last 12 months, with how many came from a campaign.', 'SELECT DATE_FORMAT(o.created_at, ''%Y-%m'') AS month, o.category, COUNT(*) AS opt_outs, SUM(CASE WHEN o.campaign_id IS NOT NULL THEN 1 ELSE 0 END) AS from_campaign FROM marketing_email_opt_outs o WHERE o.created_at >= UTC_TIMESTAMP() - INTERVAL 12 MONTH GROUP BY month, o.category ORDER BY month, o.category', 1),
('marketing-assistant-runs', 'Marketing: AI Assistant Runs', 'Marketing page assistant runs with page, mode, status, sources read, sections written, images used and claims verified or rejected.', 'SELECT mp.title AS page, ar.mode, ar.status, ar.model, ar.sources_read, ar.sections_written, ar.images_used, ar.claims_verified, ar.claims_rejected, ar.started_at, TIMESTAMPDIFF(SECOND, ar.started_at, ar.finished_at) AS duration_seconds, ar.error FROM marketing_assistant_runs ar LEFT JOIN marketing_pages mp ON mp.id = ar.page_id ORDER BY ar.started_at DESC', 1),
('custom-form-submissions-by-form', 'Custom Forms: Submissions by Form', 'Custom forms with field count, total submissions, submissions in the last 30 days, tickets raised, active share links and last submission.', 'SELECT f.name, f.slug, CASE WHEN f.active = 1 THEN ''active'' ELSE ''inactive'' END AS state, (SELECT COUNT(*) FROM custom_form_fields ff WHERE ff.form_id = f.id) AS fields, (SELECT COUNT(*) FROM custom_form_submissions s WHERE s.form_id = f.id) AS submissions, (SELECT COUNT(*) FROM custom_form_submissions s WHERE s.form_id = f.id AND s.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY) AS submissions_30_days, (SELECT COUNT(*) FROM custom_form_submissions s WHERE s.form_id = f.id AND s.ticket_id IS NOT NULL) AS tickets_raised, (SELECT COUNT(*) FROM custom_form_share_links sl WHERE sl.form_id = f.id AND sl.revoked_at IS NULL AND (sl.expires_at IS NULL OR sl.expires_at > UTC_TIMESTAMP())) AS active_share_links, (SELECT MAX(s.created_at) FROM custom_form_submissions s WHERE s.form_id = f.id) AS last_submission_at FROM custom_forms f ORDER BY submissions_30_days DESC, f.name', 1),
('custom-form-submissions-recent', 'Custom Forms: Recent Submissions', 'Custom form submissions in the last 30 days with the form, submitter and resulting ticket.', 'SELECT s.created_at, f.name AS form, us.email AS submitted_by, t.ticket_number, t.status AS ticket_status, c.name AS company FROM custom_form_submissions s JOIN custom_forms f ON f.id = s.form_id LEFT JOIN users us ON us.id = s.submitted_by LEFT JOIN tickets t ON t.id = s.ticket_id LEFT JOIN companies c ON c.id = t.company_id WHERE s.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY s.created_at DESC', 1),
('client-onboarding-pipeline', 'Client Onboarding: Invitation Pipeline', 'Client onboarding invitations with status, recipient, expiry, submission and approval times and the resulting company.', 'SELECT co.client_name, co.contact_name, co.recipient_email, co.status, co.created_at, co.expires_at, co.submitted_at, co.approved_at, TIMESTAMPDIFF(HOUR, co.created_at, co.submitted_at) AS hours_to_submit, c.name AS company, t.ticket_number, co.error_message FROM client_onboardings co LEFT JOIN companies c ON c.id = co.company_id LEFT JOIN tickets t ON t.id = co.ticket_id ORDER BY FIELD(co.status, ''submitted'', ''pending'', ''processing'', ''failed'', ''approved'', ''declined'', ''revoked''), co.created_at DESC', 1),
('companies-pending-approval', 'Companies: Awaiting Approval', 'Companies created by client onboarding that are still awaiting approval, with the onboarding submission time.', 'SELECT c.name AS company, c.phone, co.contact_name, co.recipient_email, co.submitted_at, co.status AS onboarding_status FROM companies c LEFT JOIN client_onboardings co ON co.company_id = c.id WHERE c.pending_approval = 1 ORDER BY co.submitted_at ASC', 1),
('applications-register', 'Applications: Register by Company', 'Documented line-of-business applications per company with type, version, importance, champion and linked knowledge base articles.', 'SELECT c.name AS company, ap.name AS application, ty.name AS application_type, ap.version, ap.importance, COALESCE(TRIM(CONCAT(COALESCE(st.first_name, ''''), '' '', COALESCE(st.last_name, ''''))), ap.champion_name) AS champion, (SELECT COUNT(*) FROM application_kb_links k WHERE k.application_id = ap.id) AS kb_articles, (SELECT COUNT(*) FROM application_external_links x WHERE x.application_id = ap.id) AS external_links, ap.updated_at FROM applications ap LEFT JOIN companies c ON c.id = ap.company_id LEFT JOIN application_types ty ON ty.id = ap.type_id LEFT JOIN staff st ON st.id = ap.champion_staff_id ORDER BY company, FIELD(ap.importance, ''critical'', ''high'', ''medium'', ''low''), application', 1),
('applications-importance-by-company', 'Applications: Importance Summary by Company', 'Count of documented applications per company by importance, and how many have no champion or no linked documentation.', 'SELECT c.name AS company, COUNT(*) AS applications, SUM(CASE WHEN ap.importance = ''critical'' THEN 1 ELSE 0 END) AS critical, SUM(CASE WHEN ap.importance = ''high'' THEN 1 ELSE 0 END) AS high, SUM(CASE WHEN ap.importance = ''medium'' THEN 1 ELSE 0 END) AS medium, SUM(CASE WHEN ap.importance = ''low'' THEN 1 ELSE 0 END) AS low, SUM(CASE WHEN ap.champion_staff_id IS NULL AND COALESCE(ap.champion_name, '''') = '''' THEN 1 ELSE 0 END) AS without_champion, SUM(CASE WHEN NOT EXISTS (SELECT 1 FROM application_kb_links k WHERE k.application_id = ap.id) THEN 1 ELSE 0 END) AS without_kb_article FROM applications ap LEFT JOIN companies c ON c.id = ap.company_id GROUP BY ap.company_id, c.name ORDER BY applications DESC', 1),
('backup-register', 'Backups: Backup Register', 'Documented backups per company with backup application, frequency, linked monitored job and its latest status.', 'SELECT c.name AS company, br.name AS backup, ba.name AS backup_app, br.frequency, bj.name AS monitored_job, CASE WHEN br.backup_job_id IS NULL THEN ''not linked'' ELSE ''linked'' END AS monitoring, (SELECT e.status FROM backup_job_events e WHERE e.backup_job_id = br.backup_job_id ORDER BY e.event_date DESC, e.id DESC LIMIT 1) AS latest_job_status, br.updated_at FROM backup_register br LEFT JOIN companies c ON c.id = br.company_id LEFT JOIN backup_apps ba ON ba.id = br.backup_app_id LEFT JOIN backup_jobs bj ON bj.id = br.backup_job_id ORDER BY company, backup', 1),
('business-hours-deferred-automations', 'Automations: Deferred by Business Hours', 'Automation runs deferred until business hours, with status, when they are due and any error, newest first.', 'SELECT au.name AS automation, d.event_name, c.name AS company, t.ticket_number, d.status, d.run_after, d.processed_at, d.error_message, d.created_at FROM automation_deferred_runs d LEFT JOIN automations au ON au.id = d.automation_id LEFT JOIN companies c ON c.id = d.company_id LEFT JOIN tickets t ON t.id = d.ticket_id ORDER BY FIELD(d.status, ''pending'', ''failed''), d.run_after DESC', 1),
('business-hours-closures-upcoming', 'Business Hours: Upcoming Closures', 'Global and company-specific business hours closures from today onwards.', 'SELECT bc.closure_date, bc.name, COALESCE(c.name, ''All companies'') AS company, DAYNAME(bc.closure_date) AS weekday FROM business_hours_closures bc LEFT JOIN companies c ON c.id = bc.company_id WHERE bc.closure_date >= CURRENT_DATE ORDER BY bc.closure_date, company', 1),
('smb1001-compliance-by-company', 'SMB1001: Compliance Status by Company', 'SMB1001 control status per company: compliant or not applicable, in progress, non-compliant and not started, with the completion percentage.', 'SELECT c.name AS company, COUNT(cc.id) AS controls_tracked, SUM(CASE WHEN cc.status IN (''compliant'', ''not_applicable'') THEN 1 ELSE 0 END) AS complete, SUM(CASE WHEN cc.status = ''in_progress'' THEN 1 ELSE 0 END) AS in_progress, SUM(CASE WHEN cc.status = ''non_compliant'' THEN 1 ELSE 0 END) AS non_compliant, (SELECT COUNT(*) FROM smb1001_controls) - SUM(CASE WHEN cc.status IN (''compliant'', ''not_applicable'', ''in_progress'', ''non_compliant'') THEN 1 ELSE 0 END) AS not_started, ROUND(100 * SUM(CASE WHEN cc.status IN (''compliant'', ''not_applicable'') THEN 1 ELSE 0 END) / NULLIF((SELECT COUNT(*) FROM smb1001_controls), 0), 1) AS complete_percent, MAX(cc.updated_at) AS last_updated_at FROM company_smb1001_compliance cc JOIN companies c ON c.id = cc.company_id GROUP BY cc.company_id, c.name ORDER BY complete_percent DESC', 1),
('smb1001-evidence-by-company', 'SMB1001: Evidence Uploaded by Company', 'Current SMB1001 evidence files per company with the number of controls evidenced and the last upload.', 'SELECT c.name AS company, COUNT(*) AS evidence_files, COUNT(DISTINCT e.control_id) AS controls_with_evidence, ROUND(SUM(e.file_size_bytes) / 1048576, 1) AS total_mb, MAX(e.uploaded_at) AS last_uploaded_at FROM company_smb1001_evidence e JOIN companies c ON c.id = e.company_id WHERE e.is_current = 1 GROUP BY e.company_id, c.name ORDER BY controls_with_evidence DESC', 1),
('tickets-parent-child-tasks', 'Tickets: Open Parent Tickets With Linked Child Tickets', 'Open tickets that have child tickets (created from tasks or linked as sub-tickets), with how many children are still open.', 'SELECT t.ticket_number, t.subject, c.name AS company, t.status, COUNT(ch.id) AS child_tickets, SUM(CASE WHEN ch.status NOT IN (''resolved'', ''closed'') THEN 1 ELSE 0 END) AS open_children, t.created_at FROM tickets t JOIN tickets ch ON ch.parent_ticket_id = t.id LEFT JOIN companies c ON c.id = t.company_id WHERE t.status NOT IN (''resolved'', ''closed'') GROUP BY t.id, t.ticket_number, t.subject, c.name, t.status, t.created_at ORDER BY open_children DESC, t.created_at', 1),
('kb-recurring-issue-reviews', 'Knowledge Base: Recurring Issue Reviews', 'Recurring-issue clusters reviewed for knowledge base articles: whether an article was written or the cluster ignored, and who reviewed it.', 'SELECT r.anchor_ticket_id, t.subject AS anchor_subject, CASE WHEN r.ignored = 1 THEN ''ignored'' WHEN r.article_id IS NOT NULL THEN ''article written'' ELSE ''reviewed'' END AS outcome, kb.title AS article, us.email AS reviewed_by, r.updated_at FROM knowledge_base_recurring_issue_reviews r LEFT JOIN tickets t ON t.id = r.anchor_ticket_id LEFT JOIN knowledge_base_articles kb ON kb.id = r.article_id LEFT JOIN users us ON us.id = r.updated_by ORDER BY r.updated_at DESC', 1),
('report-rmm-devices', 'Report - RMM Devices', 'The current company''s RMM-managed devices with platform, OS, last check-in, free system disk, missing updates, pending reboot and latest health score.', 'SELECT COALESCE(a.name, ag.hostname) AS device, ag.os AS platform, COALESCE(inv.os_name, ag.os_version) AS operating_system, CASE WHEN ag.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 15 MINUTE THEN ''online'' ELSE ''offline'' END AS state, ag.last_seen_utc, ROUND(inv.system_disk_free_bytes / 1073741824, 1) AS system_disk_free_gb, sc.missing_count AS missing_updates, CASE WHEN sc.reboot_pending = 1 THEN ''yes'' ELSE ''no'' END AS reboot_pending, (SELECT h.health_score FROM ai_health_checks h WHERE h.asset_id = ag.asset_id AND h.status = ''completed'' ORDER BY h.id DESC LIMIT 1) AS health_score FROM rmm_agents ag LEFT JOIN assets a ON a.id = ag.asset_id LEFT JOIN rmm_device_inventory inv ON inv.agent_id = ag.id LEFT JOIN rmm_windows_update_scans sc ON sc.agent_id = ag.id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' ORDER BY device', 1),
('report-windows-updates-missing', 'Report - Windows Updates Missing', 'Windows updates still missing on the current company''s devices, by update, with the number of devices affected.', 'SELECT u.kb, u.title, u.classification, u.severity, u.released_on, COUNT(DISTINCT u.agent_id) AS devices FROM rmm_windows_updates u JOIN rmm_agents ag ON ag.id = u.agent_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND u.is_hidden = 0 GROUP BY u.update_id, u.kb, u.title, u.classification, u.severity, u.released_on ORDER BY devices DESC, u.released_on', 1),
('report-health-checks', 'Report - Device Health Checks', 'The latest completed AI health check for each of the current company''s devices with status, score and summary.', 'SELECT a.name AS device, h.overall_status, h.health_score, h.completed_at, h.summary FROM ai_health_checks h JOIN (SELECT asset_id, MAX(id) AS id FROM ai_health_checks WHERE status = ''completed'' GROUP BY asset_id) latest ON latest.id = h.id LEFT JOIN assets a ON a.id = h.asset_id WHERE h.company_id = {{current.company}} ORDER BY FIELD(h.overall_status, ''critical'', ''attention'', ''healthy''), h.health_score', 1),
('report-warranty-status', 'Report - Asset Warranty Status', 'The current company''s active assets with warranty dates, expired or expiring flags and days remaining.', 'SELECT a.name AS asset, a.asset_type, a.serial_number, a.warranty_end_date, CASE WHEN a.warranty_end_date IS NULL THEN ''unknown'' WHEN a.warranty_end_date < CURRENT_DATE THEN ''expired'' WHEN a.warranty_end_date <= CURRENT_DATE + INTERVAL 90 DAY THEN ''expiring'' ELSE ''covered'' END AS warranty_state, DATEDIFF(a.warranty_end_date, CURRENT_DATE) AS days_remaining FROM assets a WHERE a.company_id = {{current.company}} AND a.archived_at IS NULL ORDER BY a.warranty_end_date IS NULL, a.warranty_end_date', 1),
('report-software-inventory', 'Report - Software Inventory', 'Applications installed across the current company''s RMM-managed devices with device counts and versions.', 'SELECT s.name AS application, MAX(s.publisher) AS publisher, COUNT(DISTINCT s.agent_id) AS devices, GROUP_CONCAT(DISTINCT s.version ORDER BY s.version SEPARATOR '', '') AS versions FROM rmm_device_software s JOIN rmm_agents ag ON ag.id = s.agent_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' GROUP BY s.name ORDER BY devices DESC, application', 1),
('report-rmm-script-activity', 'Report - Maintenance Script Activity (Last 30 Days)', 'Scripts run on the current company''s devices in the last 30 days with run, completed and failed counts.', 'SELECT r.script_name, COUNT(*) AS runs, SUM(CASE WHEN r.status = ''completed'' THEN 1 ELSE 0 END) AS completed, SUM(CASE WHEN r.status IN (''failed'', ''timed_out'') THEN 1 ELSE 0 END) AS failed, COUNT(DISTINCT r.agent_id) AS devices, MAX(r.completed_at) AS last_completed_at FROM rmm_script_runs r WHERE r.company_id = {{current.company}} AND r.queued_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY r.script_name ORDER BY runs DESC', 1),
('report-applications', 'Report - Applications Register', 'The current company''s documented applications with type, version, importance and champion.', 'SELECT ap.name AS application, ty.name AS application_type, ap.version, ap.importance, COALESCE(TRIM(CONCAT(COALESCE(st.first_name, ''''), '' '', COALESCE(st.last_name, ''''))), ap.champion_name) AS champion FROM applications ap LEFT JOIN application_types ty ON ty.id = ap.type_id LEFT JOIN staff st ON st.id = ap.champion_staff_id WHERE ap.company_id = {{current.company}} ORDER BY FIELD(ap.importance, ''critical'', ''high'', ''medium'', ''low''), application', 1),
('stat-strip-rmm-overview', 'Stat Strip - RMM - Fleet Overview', 'Active RMM agents, online now, offline over 7 days, failing checks, script runs and failures today, and open findings.', 'SELECT (SELECT COUNT(*) FROM rmm_agents ag WHERE ag.status = ''active'') AS agents, (SELECT COUNT(*) FROM rmm_agents ag WHERE ag.status = ''active'' AND ag.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 15 MINUTE) AS online, (SELECT COUNT(*) FROM rmm_agents ag WHERE ag.status = ''active'' AND (ag.last_seen_utc IS NULL OR ag.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 7 DAY)) AS stale_agents, (SELECT COUNT(*) FROM rmm_check_states st JOIN rmm_checks ch ON ch.id = st.check_id WHERE ch.is_enabled = 1 AND st.status = ''failing'') AS failing_checks, (SELECT COUNT(*) FROM rmm_script_runs r WHERE r.queued_at >= UTC_DATE()) AS script_runs_today, (SELECT COUNT(*) FROM rmm_script_runs r WHERE r.queued_at >= UTC_DATE() AND r.status IN (''failed'', ''timed_out'')) AS failed_runs_today, (SELECT COUNT(*) FROM rmm_findings f WHERE f.is_active = 1 AND f.status = ''open'') AS open_findings', 1),
('stat-strip-windows-updates', 'Stat Strip - Windows Updates - Overview', 'Devices scanned, devices with missing updates, missing security updates, devices awaiting a reboot and failed installs in the last 30 days.', 'SELECT (SELECT COUNT(*) FROM rmm_windows_update_scans sc JOIN rmm_agents ag ON ag.id = sc.agent_id WHERE ag.status = ''active'') AS devices_scanned, (SELECT COUNT(*) FROM rmm_windows_update_scans sc JOIN rmm_agents ag ON ag.id = sc.agent_id WHERE ag.status = ''active'' AND sc.missing_count > 0) AS devices_missing_updates, (SELECT COUNT(*) FROM rmm_windows_updates u JOIN rmm_agents ag ON ag.id = u.agent_id WHERE ag.status = ''active'' AND u.is_hidden = 0 AND u.classification LIKE ''%Security%'') AS missing_security_updates, (SELECT COUNT(*) FROM rmm_windows_update_scans sc JOIN rmm_agents ag ON ag.id = sc.agent_id WHERE ag.status = ''active'' AND sc.reboot_pending = 1) AS reboot_pending, (SELECT COUNT(*) FROM rmm_windows_update_history h WHERE h.operation = ''install'' AND h.result = ''failed'' AND h.occurred_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY) AS failed_installs', 1),
('stat-strip-health-checks', 'Stat Strip - Health Checks - Overview', 'Devices with a completed health check, average score, healthy, attention and critical devices, and health checks run in the last 30 days.', 'SELECT COUNT(*) AS devices_checked, ROUND(AVG(h.health_score), 0) AS average_score, SUM(CASE WHEN h.overall_status = ''healthy'' THEN 1 ELSE 0 END) AS healthy, SUM(CASE WHEN h.overall_status = ''attention'' THEN 1 ELSE 0 END) AS attention, SUM(CASE WHEN h.overall_status = ''critical'' THEN 1 ELSE 0 END) AS critical, (SELECT COUNT(*) FROM ai_health_checks x WHERE x.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY) AS checks_last_30_days FROM ai_health_checks h JOIN (SELECT asset_id, MAX(id) AS id FROM ai_health_checks WHERE status = ''completed'' GROUP BY asset_id) latest ON latest.id = h.id', 1),
('stat-strip-llm-usage', 'Stat Strip - AI Usage - Last 30 Days', 'LLM requests, failures, input and output tokens (input_tok, output_tok), features used and average latency over the last 30 days.', 'SELECT COUNT(*) AS requests, SUM(CASE WHEN u.status IN (''error'', ''failed'') THEN 1 ELSE 0 END) AS failed, COALESCE(SUM(u.input_tokens), 0) AS input_tok, COALESCE(SUM(u.output_tokens), 0) AS output_tok, COUNT(DISTINCT u.feature) AS features, ROUND(AVG(u.duration_ms), 0) AS avg_duration_ms FROM llm_usage_events u WHERE u.occurred_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY', 1),
('stat-strip-tray-overview', 'Stat Strip - Tray - Overview', 'Active tray devices, seen in the last day, not seen in 30 days, Windows and macOS devices and active deployment URLs.', 'SELECT COUNT(*) AS devices, SUM(CASE WHEN td.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 1 DAY THEN 1 ELSE 0 END) AS seen_today, SUM(CASE WHEN td.last_seen_utc IS NULL OR td.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 30 DAY THEN 1 ELSE 0 END) AS stale, SUM(CASE WHEN td.os = ''windows'' THEN 1 ELSE 0 END) AS windows, SUM(CASE WHEN td.os = ''darwin'' THEN 1 ELSE 0 END) AS macos, (SELECT COUNT(*) FROM tray_deployment_links l WHERE l.revoked_at IS NULL AND (l.expires_at IS NULL OR l.expires_at > UTC_TIMESTAMP())) AS deployment_urls FROM tray_devices td WHERE td.status = ''active''', 1),
('stat-strip-marketing-campaigns', 'Stat Strip - Marketing - Campaigns', 'Campaigns sent, emails sent, opened, clicked, replied and bounced across all marketing campaigns, and opt-outs in the last 30 days.', 'SELECT (SELECT COUNT(*) FROM marketing_campaigns mc WHERE mc.status = ''completed'') AS campaigns_completed, SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END) AS sent, SUM(CASE WHEN r.first_opened_at IS NOT NULL THEN 1 ELSE 0 END) AS opened, SUM(CASE WHEN r.first_clicked_at IS NOT NULL THEN 1 ELSE 0 END) AS clicked, SUM(CASE WHEN r.replied_at IS NOT NULL THEN 1 ELSE 0 END) AS replied, SUM(CASE WHEN r.bounced_at IS NOT NULL THEN 1 ELSE 0 END) AS bounced, (SELECT COUNT(*) FROM marketing_email_opt_outs o WHERE o.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY) AS opt_outs_30_days FROM marketing_campaign_recipients r', 1),
('stat-strip-report-rmm-devices', 'Stat Strip - Company Overview - RMM Devices', 'The current company''s RMM devices: total, online, offline, awaiting reboot, devices with missing updates and failing checks.', 'SELECT COUNT(*) AS devices, SUM(CASE WHEN ag.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 15 MINUTE THEN 1 ELSE 0 END) AS online, SUM(CASE WHEN ag.last_seen_utc IS NULL OR ag.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 15 MINUTE THEN 1 ELSE 0 END) AS offline, (SELECT COUNT(*) FROM rmm_windows_update_scans sc JOIN rmm_agents a2 ON a2.id = sc.agent_id WHERE a2.company_id = {{current.company}} AND a2.status = ''active'' AND sc.reboot_pending = 1) AS reboot_pending, (SELECT COUNT(*) FROM rmm_windows_update_scans sc JOIN rmm_agents a2 ON a2.id = sc.agent_id WHERE a2.company_id = {{current.company}} AND a2.status = ''active'' AND sc.missing_count > 0) AS missing_updates, (SELECT COUNT(*) FROM rmm_check_states st JOIN rmm_checks ch ON ch.id = st.check_id JOIN rmm_agents a2 ON a2.id = st.agent_id WHERE a2.company_id = {{current.company}} AND a2.status = ''active'' AND ch.is_enabled = 1 AND st.status = ''failing'') AS failing_checks FROM rmm_agents ag WHERE ag.company_id = {{current.company}} AND ag.status = ''active''', 1),
('stat-strip-report-health-checks', 'Stat Strip - Company Overview - Device Health', 'The current company''s latest health check per device: devices checked, average score, healthy, attention and critical.', 'SELECT COUNT(*) AS devices_checked, ROUND(AVG(h.health_score), 0) AS average_score, SUM(CASE WHEN h.overall_status = ''healthy'' THEN 1 ELSE 0 END) AS healthy, SUM(CASE WHEN h.overall_status = ''attention'' THEN 1 ELSE 0 END) AS attention, SUM(CASE WHEN h.overall_status = ''critical'' THEN 1 ELSE 0 END) AS critical FROM ai_health_checks h JOIN (SELECT asset_id, MAX(id) AS id FROM ai_health_checks WHERE status = ''completed'' GROUP BY asset_id) latest ON latest.id = h.id WHERE h.company_id = {{current.company}}', 1),
('stat-strip-report-warranty', 'Stat Strip - Company Overview - Warranty', 'The current company''s active assets by warranty: covered, expiring in 90 days, expired and unknown.', 'SELECT COUNT(*) AS assets, SUM(CASE WHEN a.warranty_end_date > CURRENT_DATE + INTERVAL 90 DAY THEN 1 ELSE 0 END) AS covered, SUM(CASE WHEN a.warranty_end_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL 90 DAY THEN 1 ELSE 0 END) AS expiring, SUM(CASE WHEN a.warranty_end_date < CURRENT_DATE THEN 1 ELSE 0 END) AS expired, SUM(CASE WHEN a.warranty_end_date IS NULL THEN 1 ELSE 0 END) AS unknown FROM assets a WHERE a.company_id = {{current.company}} AND a.archived_at IS NULL', 1),
('dashboard-rmm-devices-by-os', 'Dashboard - RMM devices by operating system', 'The current company''s active RMM devices grouped by operating system (X) with device counts (Y).', 'SELECT COALESCE(inv.os_name, ag.os_version, ag.os, ''Unknown'') AS X, COUNT(*) AS Y FROM rmm_agents ag LEFT JOIN rmm_device_inventory inv ON inv.agent_id = ag.id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' GROUP BY X ORDER BY Y DESC', 1),
('dashboard-missing-updates-by-classification', 'Dashboard - Missing Windows updates by classification', 'The current company''s missing (not hidden) Windows updates by classification (X) with update counts (Y).', 'SELECT COALESCE(u.classification, ''Unclassified'') AS X, COUNT(*) AS Y FROM rmm_windows_updates u JOIN rmm_agents ag ON ag.id = u.agent_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND u.is_hidden = 0 GROUP BY X ORDER BY Y DESC', 1),
('dashboard-health-check-status', 'Dashboard - Device health status', 'The current company''s latest health check per device by overall status (X) with device counts (Y).', 'SELECT COALESCE(h.overall_status, ''unknown'') AS X, COUNT(*) AS Y FROM ai_health_checks h JOIN (SELECT asset_id, MAX(id) AS id FROM ai_health_checks WHERE status = ''completed'' GROUP BY asset_id) latest ON latest.id = h.id WHERE h.company_id = {{current.company}} GROUP BY X ORDER BY Y DESC', 1),
('dashboard-script-runs-by-day', 'Dashboard - RMM script runs by day', 'Script runs on the current company''s devices per day (X) over the last 30 days (Y).', 'SELECT DATE(r.queued_at) AS X, COUNT(*) AS Y FROM rmm_script_runs r WHERE r.company_id = {{current.company}} AND r.queued_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY X ORDER BY X', 1),
('dashboard-global-llm-requests-by-day', 'Dashboard - Global AI requests by day', 'LLM requests per day (X) across the portal over the last 30 days (Y).', 'SELECT DATE(u.occurred_at) AS X, COUNT(*) AS Y FROM llm_usage_events u WHERE u.occurred_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY X ORDER BY X', 1),
('dashboard-global-rmm-agents-by-company', 'Dashboard - Global RMM agents by company', 'Active RMM agents per company (X) across the portal (Y).', 'SELECT COALESCE(c.name, ''Unassigned'') AS X, COUNT(*) AS Y FROM rmm_agents ag LEFT JOIN companies c ON c.id = ag.company_id WHERE ag.status = ''active'' GROUP BY X ORDER BY Y DESC', 1);
